import{z as m,x as p,o as l,c as d,q as i,j as o,D as e,d as r,s,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"集总参数模型","description":"","frontmatter":{"title":"集总参数模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lumped-parameter-model.md","filePath":"litho/lumped-parameter-model.md","lastUpdated":1791063341000}'),B={name:"litho/lumped-parameter-model.md"};function A(h,a,D,P,C,u){const E=p("Mermaid");return l(),d("div",null,[a[2]||(a[2]=i('<h1 id="集总参数模型" tabindex="-1">集总参数模型 <a class="header-anchor" href="#集总参数模型" aria-label="Permalink to &quot;集总参数模型&quot;">​</a></h1><div class="epigraph"><p>不必每次都解三维反应–扩散加溶解前沿：把胶收成对比、清场剂量与有效厚度几个数，也能预言 CD 对剂量怎么走。</p><footer>—— C. A. Mack，光刻集总参数模型（LPM）；亦见 *Fundamental Principles of Optical Lithography*</footer></div><p><a href="/litho/development-rate-model">上一课</a>把浮雕写成 \\(R(m)\\) 的三维积分。缺口是：曝光矩阵要扫的是 CD 对剂量（以及后课的焦），全 PDE 对手算和快速 OPC 过重。本课钉 Mack 的集总参数模型（lumped parameter model, LPM）。三维轮廓仿真何时必须回去，留给<a href="/litho/resist-profile-simulation">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LPM 的想法：沿厚度把吸收、漂白、显影时间收成有效剂量与有效速率，再用胶衬度把空中像强度映射到边位置。典型输入包括 \\(E_0\\) 一类清场锚点、衬度 \\(\\gamma\\)、胶厚与吸收，输出是给定空中像剖线下的 CD。它不声称侧壁波纹、残胶形貌或倒塌。</p><p><span class="marginnote">术语翻译：「集总」（lumped）就是把沿胶厚方向每点都不同的吸收、酸浓度、溶解速率，打包成几个等效参数（有效剂量、\\(\\gamma\\)、有效厚度）——像把一段山路收成「总里程加平均坡度」，不画等高线也能估骑行时间。</span></p><p>缺口不是再定义 \\(\\gamma\\)——主干<a href="/litho/resist-contrast-curve">衬度曲线</a>已经定义——而是承认：产线大量「剂量–CD」预言走的是这条降阶链，不是每场解 RD。把 LPM 当成「没有物理的拟合直线」，会在换胶厚或换 \\(B\\) 时不知道该动哪个集总量。</p><h3 id="集总掉的是-不是光学" tabindex="-1">集总掉的是 \\(z\\)，不是光学 <a class="header-anchor" href="#集总掉的是-不是光学" aria-label="Permalink to &quot;集总掉的是 $z$，不是光学&quot;">​</a></h3><p>空中像 \\(I(x)\\) 仍来自 Hopkins / TCC。LPM 集总的是胶对这条剖线的响应。离焦改的是 \\(I(x;z_\\mathrm{focus})\\)，可以送进同一 LPM，于是 Bossung 能被近似画出来——精度止于「厚度方向已经被平均」。驻波很强时平均撒谎，必须回到上一课的分层 \\(R\\)。</p><p><span class="marginnote">LPM 与 OPC 的 CM1 可变阈值是亲戚：都把胶收成少参数。CM1 面向全芯片二维环境；LPM 面向一维剖线与工艺直觉。不要把两个商品名考据成互斥物理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标定：大垫测 \\(E_0\\)、\\(\\gamma\\)、厚与 ABC；密线测一组 CD(E) 修有效参数。预言：取空中像阈值附近的 ILS，用集总衬度估计 \\(\\Delta\\mathrm{CD}/(\\Delta E/E)\\)。这与 <a href="/litho/nils-ils">NILS</a> 课的光学预言同构，差别是 \\(\\gamma\\) 与吸收已经折进有效斜率。</p><p><span class="marginnote">数字实例：集总衬度给出的近似是 \\(\\Delta\\mathrm{CD}/\\mathrm{CD}\\approx(\\Delta E/E)/\\gamma\\)。若 \\(\\gamma=5\\)、剂量漂 5%，线宽相对变化约 1%——100 nm 的线漂约 1 nm。衬度越高的胶，同一剂量漂移咬出的 CD 漂移越小。</span></p><p>换 BARC、换胶厚，先改光学 \\(I(z)\\) 的积分，再改 LPM 的有效 \\(E_0\\)。只拧「阈值强度百分比」而不改吸收项，是把薄膜课的 swing 藏进胶参数，换衬底就会炸。</p>',14)),(l(),o(n,null,{default:e(()=>[s(E,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%89%96%E7%BA%BF%22%5D%20--%3E%20LPM%5B%22LPM%3A%20E0%20%CE%B3%20%E5%90%B8%E6%94%B6%20%E5%8E%9A%22%5D%0A%20%20ABC%5B%22Dill%20A%20B%20C%22%5D%20--%3E%20LPM%0A%20%20LPM%20--%3E%20CD%5B%22CD(E)%22%5D%0A%20%20LPM%20--%3E%20PROF%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%BF%85%E8%A6%81%E6%97%B6%E5%9B%9E%E4%B8%89%E7%BB%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"清底要求沿 \\(z\\) 的剂量积分够把 \\(m\\) 降到 \\(R\\) 能在给定时间内挖穿。集总把这道积分换成「有效剂量 ≥ \\(E_0\\)」。边的位置由横向强度落到有效阈值之处决定；\\(\\gamma\\) 越大，有效阈值越接近开关，CD 对 ILS 越敏感。吸收 \\(B\\) 大，底部有效剂量低，同一表面强度下 \\(E_0\\) 抬高——薄膜高 \\(k\\) 的 EUV 胶尤其如此，上一课程的薄膜效应在这里变成 LPM 的一个数。",-1)),a[5]||(a[5]=t("p",null,"酸扩散核可以再集总进「有效模糊后的空中像」，然后才进阈值。顺序不能反：先阈值再模糊，边会偏锐。",-1)),(l(),o(n,null,{default:e(()=>[s(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I(x)%22%5D%20--%3E%20BLUR%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%E6%A8%A1%E7%B3%8A%20(%E6%A0%B8%E5%8D%B7%E7%A7%AF)%22%5D%0A%20%20BLUR%20--%3E%20EFF%5B%22%E6%9C%89%E6%95%88%E6%A8%A1%E7%B3%8A%E5%83%8F%22%5D%0A%20%20EFF%20--%3E%20THR%5B%22%E9%98%88%E5%80%BC%E5%88%87%E5%89%B2%22%5D%0A%20%20THR%20--%3E%20EDGE%5B%22%E8%BE%B9%E4%BD%8D%E7%BD%AE%20%2F%20CD%22%5D%0A%20%20WRONG%5B%22%E9%94%99%E8%AF%AF%E9%A1%BA%E5%BA%8F%3A%20%E5%85%88%E9%98%88%E5%80%BC%E5%86%8D%E6%A8%A1%E7%B3%8A%22%5D%20-.-%3E%7C%22%E8%BE%B9%E4%BC%9A%E5%81%8F%E9%94%90%22%7C%20THR%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">Mack 原文 LPM 针对 DNQ 正胶与接触/邻近印刷的剂量响应。CAR 仍可用同一骨架，但 \\(E_0\\) 强烈依赖 PEB，集总参数必须与烘箱绑定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>LPM 不预测 LWR、不预测缺孔尾、不预测三维 footing。下一课的轮廓仿真补几何；随机单元补计数。也不要把 LPM 的 \\(E_0\\) 与扫描机剂量传感器读数混成一个校准——传感器在光学，LPM 在胶。</p><p><span class="marginnote">常见误区：把 LPM 的 \\(E_0\\) 当成扫描机剂量读数去校。\\(E_0\\) 是胶里的清场剂量锚点，随胶批次、烘箱与膜厚变；扫描机剂量是机台设定的光学量。两者隔着 PEB 与吸收，混用会把胶的账记到机台头上。</span></p><p>High-NA 胶厚预算已经很薄，沿 \\(z\\) 可集总的东西变少，LPM 误差相对变大，更常要轮廓仿真。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LPM 把 ABC、厚度、\\(\\gamma\\)、\\(E_0\\) 收成剖线级 CD 预言。</li><li>集总的是胶的 \\(z\\) 向积分，不是 TCC。</li><li>驻波强、要侧壁或残胶时，回到三维 \\(R\\)。</li><li>CAR 的 LPM 必须与 PEB 绑定。</li><li>出处：Mack 集总参数模型；<em>Fundamental Principles of Optical Lithography</em>。</li></ul>',7))])}const L=m(B,[["render",A]]);export{c as __pageData,L as default};
